-- ===================== GDOCS =====================
INSERT INTO gdocs.docs_documents (document_id, title, owner_email, shared_with_emails_json, visibility, body_text, style_runs_json, revision_id, drive_file_id, created_time, modified_time)
VALUES ('f_1326e66bcabfda8fd29e4a', 'Close-out register conventions', 'Resource: 7240535625619857401', '["leonard.hayes@harmonygames.co", "arthur.blake@harmonygames.co", "robert@harmonygames.co"]', 'private', E'Close-out register conventions\n1. One row per vendor account. If the same vendor shows up twice (two issues, two names), it''s one row under the name on its invoice, and the newer issue is the duplicate.\n2. Leave out people, contractors and professional firms (legal, accounting, Sunset), taxes and filing services, insurance, bank fees, one-off purchases, anything the company itself never paid for, and anything cancelled before Feb 9. Exception: anything on Sunset''s list goes on the register whatever else applies.\n3. Arthur''s project came from the P&L and our lists; he skipped one-off, filing and insurance lines and ones long gone. AWS and the ad accounts in the UA line stay off the register: he and I are closing those out ourselves. Before you call it complete, add what it misses inside any other costs-tab line that covers several vendors — each account there gets its own row.\n4. What we do: Cancel, Keep (my keep list, as amended in the thread), Move to Arthur''s LLC (his card), or Hold for Sunset. Sunset''s list wins over everything above.\n5. Where it stands, for Cancel rows only: Closed = the vendor itself has confirmed (their email, an in-app or bot notice, a final invoice) — say where. Requested = one of us has cancelled or asked but nothing has come back from the vendor. Open = nobody has done anything yet. Leave it blank on the other rows.\n6. By when: for Cancel rows that aren''t Closed, the day before the next charge (for accounts billed on usage — ads, cloud — use Feb 28), or the SVB card on the founders'' board if it sets an earlier date. For Keep and Hold rows still charging the SVB card while we need them, follow SVB''s card terms. Hold rows already off that card, or that won''t charge it again before Sunset''s review call, stay until the review call; Keep rows that aren''t on the SVB card get a dash. Moved and Closed rows get a dash, unless an export or a switch-over still has to happen before the access ends — then the day before it ends.\n7. Owner: the Linear assignee unless the issue hands it to someone else. Anything you add is yours.\n8. Monthly cost, rounded to cents: the monthly figure its owner gives in its Linear issue, or else its own last invoice or receipt brought to a month (annual ÷ 12, quarterly ÷ 3). Free plans and accounts that have never charged us are 0.\n9. Two totals at the bottom: the sum of the monthly cost column over every row (what it all costs us today), and the same sum over the Keep and Hold rows only (what''s left after the plan).\n10. A clash is a decision one of us already posted in #winddown that Sunset''s list or SVB''s card terms would undo. Moving who pays for an account isn''t one (it closes nothing), and requests or suggestions aren''t decisions.\n', '[{"start": 0, "end": 31, "named_style": "TITLE", "list_id": null, "list_nesting": 0}, {"start": 31, "end": 2727, "named_style": "NORMAL_TEXT", "list_id": null, "list_nesting": 0}]', '8b9413d402', 'f_1326e66bcabfda8fd29e4a', '2026-02-13T16:38:02Z', '2026-02-13T16:58:40Z');
