INSERT INTO confluence.confluence_pages (id, space_id, parent_id, title, body, body_format, status, version, author_id, created_at, updated_at)
VALUES ('page_ua_vendor_closeout', 'space_OPS', 'page_ops_home', 'Vendor close-out conventions (Growth/UA)', '<p>How Growth/UA closes out an ad network or attribution vendor in the UA vendor tracker: 1. Pause every campaign; the vendor counts as closed once spend reads $0 for 7 days.</p><p>2. Cost in the tracker = trailing 30-day spend.</p><p>3. Owner = the UA manager on the account.</p><p>These conventions apply to the Growth/UA team''s tracker only.</p>', 'storage', 'current', 1, 'user_EMPLOYEE_0008', '2025-03-18T15:20:00Z', '2025-03-18T15:20:00Z');
INSERT INTO confluence.confluence_page_versions (id, page_id, number, title, body, author_id, message, created_at)
VALUES ('ver_64b0ed607e093b18a698fb883a584aa6', 'page_ua_vendor_closeout', 1, 'Vendor close-out conventions (Growth/UA)', '<p>How Growth/UA closes out an ad network or attribution vendor in the UA vendor tracker: 1. Pause every campaign; the vendor counts as closed once spend reads $0 for 7 days.</p><p>2. Cost in the tracker = trailing 30-day spend.</p><p>3. Owner = the UA manager on the account.</p><p>These conventions apply to the Growth/UA team''s tracker only.</p>', 'user_EMPLOYEE_0008', NULL, '2025-03-18T15:20:00Z');
