VALUES ('698fa9f7f77cecfe5c7aa524', 'commentCard', '2026-02-13T22:47:19Z', 'PERSON_6094_TRELLO_USER_ID', '640643a3fd8f3ca308d9318e', '698f48be4ba0affafbf153db', '{"board": {"id": "640643a3fd8f3ca308d9318e", "name": "Harmony Games", "shortLink": "f4LGcmuh"}, "card": {"id": "698f48be4ba0affafbf153db", "idShort": 456, "name": "SVB card payoff + closure", "shortLink": "FR0HGGrp"}, "idCard": "698f48be4ba0affafbf153db", "list": {"id": "640643a3fd8f3ca308d93195", "name": "To Do"}, "text": "Bank called back: the payoff posted early, so they close the card on the 18th, not the 20th. Anything we keep has to be off it by end of day the 17th. And let''s not drag the cancellations out either: everything we''re cancelling gets cancelled by end of day the 17th, wherever it bills. Only exception is carta, that renewal is in august and stays as I said.", "textData": {"emoji": {}}}');
