VALUES ('arthur.blake@harmonygames.co/<CAS-TQ8VVR3eSFKWcX8_qppbQEILXpnhEbstiMuR@mail.gmail.com>', 'arthur.blake@harmonygames.co/1856945900225226172', 'arthur.blake@harmonygames.co', '["INBOX", "IMPORTANT", "CATEGORY_PERSONAL"]', 'Leonard, As promised on our call, here is the checklist we run on an assignment for the benefit of creditors: 1. Cancel every subscription r', 1770921612000, '2026-02-12T18:40:12Z', 1284, 'Wind-down checklist – Harmony Games', 'PERSON_0728_EMAIL', 'PERSON_0728_NAME', '["leonard hayes <leonard.hayes@harmonygames.co>"]', '["robert <robert@harmonygames.co>", "arthur blake <arthur.blake@harmonygames.co>"]', '[]', '[]', E'Leonard,\r\n\r\nAs promised on our call, here is the checklist we run on an assignment for the benefit of creditors:\r\n1. Cancel every subscription right away except payroll and accounting.\r\n2. Export whatever records you need before you cancel.\r\n3. Close the company cards last, once nothing bills them.\r\n\r\nIf you decide to engage us we would run this for you.\r\n\r\nBest,\r\nSherwood Partners', NULL, '[{"name": "Message-ID", "value": "<CAS-TQ8VVR3eSFKWcX8_qppbQEILXpnhEbstiMuR@mail.gmail.com>"}, {"name": "Date", "value": "Thu, 12 Feb 2026 18:40:12 +0000"}, {"name": "Subject", "value": "Wind-down checklist – Harmony Games"}, {"name": "From", "value": "PERSON_0728_NAME <PERSON_0728_EMAIL>"}, {"name": "To", "value": "leonard hayes <leonard.hayes@harmonygames.co>"}, {"name": "Cc", "value": "robert <robert@harmonygames.co>, arthur blake <arthur.blake@harmonygames.co>"}]', NULL, NULL, NULL, '[]');
INSERT INTO gmail.gmail_threads (id, user_email, snippet, history_id)
VALUES ('robert@harmonygames.co/1856965916492026238', 'robert@harmonygames.co', 'Hi Leonard, Robert, Arthur, Thanks for signing today. Before we can deliver the licensed data set, these accounts need to stay active with t', NULL);
INSERT INTO gmail.gmail_messages (id, thread_id, user_email, label_ids_json, snippet, internal_date, date, size_estimate, subject, from_email, from_name, to_json, cc_json, bcc_json, reply_to_json, body_text, body_html, headers_json, in_reply_to, "references", mbox_from, attachments_meta_json)
VALUES ('robert@harmonygames.co/<CAJJpzSHRqB32RlDrDy2t2WCVuJkOmMr2sKoQuBV@mail.gmail.com>', 'robert@harmonygames.co/1856965916492026238', 'robert@harmonygames.co', '["INBOX", "IMPORTANT", "CATEGORY_PERSONAL"]', 'Hi Leonard, Robert, Arthur, Thanks for signing today. Before we can deliver the licensed data set, these accounts need to stay active with t', 1770940701000, '2026-02-12T23:58:21Z', 1764, 'Harmony Games – data delivery checklist', 'PERSON_7731_EMAIL', 'PERSON_7731_NAME', '["leonard hayes <leonard.hayes@harmonygames.co>"]', '["robert <robert@harmonygames.co>", "arthur blake <arthur.blake@harmonygames.co>"]', '[]', '[]', E'Hi Leonard, Robert, Arthur,\r\n\r\nThanks for signing today. Before we can deliver the licensed data set, these accounts need to stay active with their full history and every user in place until we confirm delivery: Slack (stay on the paid plan — the free plan hides history older than 90 days), Google Workspace (every user account, including former staff — please don''t archive or delete any), Figma, Linear, GitHub and Metabase. Nothing on this list should be closed, downgraded or archived before the delivery review call Leonard booked with us. Accounts that aren''t on the list aren''t part of the licensed bundle, so close them whenever suits you.\r\n\r\nFor Helpshift, please export the full ticket history to Drive before your subscription ends.\r\n\r\nIf our engineers change anything on this list, we''ll reply on this thread.\r\n\r\nBest,\r\nMaya\r\nClient onboarding, Sunset', NULL, '[{"name": "Message-ID", "value": "<CAJJpzSHRqB32RlDrDy2t2WCVuJkOmMr2sKoQuBV@mail.gmail.com>"}, {"name": "Date", "value": "Thu, 12 Feb 2026 23:58:21 +0000"}, {"name": "Subject", "value": "Harmony Games – data delivery checklist"}, {"name": "From", "value": "PERSON_7731_NAME <PERSON_7731_EMAIL>"}, {"name": "To", "value": "leonard hayes <leonard.hayes@harmonygames.co>"}, {"name": "Cc", "value": "robert <robert@harmonygames.co>, arthur blake <arthur.blake@harmonygames.co>"}]', NULL, NULL, NULL, '[]');
