INSERT INTO linear.linear_projects (id, team_id, name, summary, description, lead_id, priority, state, start_date, target_date, labels_json, links_json, is_archived, created_at, updated_at)
VALUES ('3f0c6a52-ee13-4b1e-68e3-a74bcc33818a', 'team_ENG', 'Shutdown – accounts', NULL, 'One issue per vendor we still pay or only recently stopped, taken from the January P&L costs tab, old receipts and the #winddown lists. I skipped the costs-tab lines that were one-off buys, filings and insurance, or already dead. This replaces my subscriptions sheet from Tuesday. A few costs-tab lines are filed under other names: the $6,250 one is Singular and the hosting one is GitHub; the two $30 game-ops lines I''m handling myself, so they''re not in here. AWS and the ad accounts in the UA line aren''t in here either: I''m shutting AWS down myself once the store transfer is done, and Leonard is closing the ad networks directly. Settle them as you go: Done once the account counts as closed in the register (access can run out later), Canceled if it doesn''t belong on the list, everything else stays open — and leave a comment on each with what happens and by when.', 'usr_cc3e90160f490686', 0, 'started', '2026-02-12', NULL, '[]', '[]', false, '2026-02-12T23:24:10Z', '2026-02-12T23:24:10Z');
